// c 8: alle Zeilen -> { veroeffentlichen, zeilen: [{ zeile, felder, hinweise }], alarme }. Mehr als die Hoechstzahl -> keine.
function planeFreigaben(zeilen, items, sperrzeilen, ctx, k) {
