  var zaehl = {};
  aus.forEach(function (b) { zaehl[b.bewertung_id] = (zaehl[b.bewertung_id] || 0) + 1; });
  aus.forEach(function (b) { if (zaehl[b.bewertung_id] > 1) b.mangel.push('reviewId doppelt'); }); // Sicherung reviewId doppelt
